import type { Lesson, MonthPlan, QuizQuestion } from '../types'

const q = (prompt: string, options: string[], answer: number, explanation: string): QuizQuestion => ({ prompt, options, answer, explanation })

function lesson(
  id: string, month: number, week: number, title: string, type: Lesson['type'], difficulty: Lesson['difficulty'], duration: number,
  topics: string[], objective: string, concept: string, why: string, example: string, explanation: string,
  exercise: string, expected: string, check: string, options: string[], answer: number, feedback: string,
): Lesson {
  return {
    id, month, week, title, type, difficulty, duration, topics, objective, concept, why, example, explanation,
    mistakes: [`Treating ${topics[0]} as a rule to memorize instead of connecting it to a business requirement.`, 'Changing several things at once, then losing track of which change caused the result.'],
    exercise, expected, checkpoints: [check, `Can you explain one likely failure case for ${topics[0]} and how you would investigate it?`],
    quiz: [q(check, options, answer, feedback)],
  }
}

