export const lessons: Lesson[] = [
  lesson('m1-sap',1,1,'What SAP, ERP, and S/4HANA solve','Theory','Beginner',35,['SAP','ERP','S/4HANA'],'Describe SAP as enterprise software and explain how an ERP connects processes and shared data.','An ERP coordinates work across finance, sales, procurement, and inventory. S/4HANA is SAP’s current ERP product family; the exact deployment and extensibility options depend on edition and release.','ABAP work has business meaning: a purchase order report must agree with how procurement and finance use the document.','Business process → SAP application → ABAP logic → database','The arrows show the request path at a high level. A developer traces how a user action becomes application behavior and persisted data.','Draw a procure-to-pay flow with one system object at each step, then describe where custom ABAP might add a report.','A short diagram connecting requisition, purchase order, goods receipt, invoice, and accounting document.','What does ERP connect?',['Separate company processes','Business processes and shared information','Only source code','Only user screens'],1,'ERP integrates processes and the information those processes need.'),
  lesson('m1-processes',1,1,'Business context: MM, SD, and FI','Theory','Beginner',40,['MM','SD','FI','Purchase order','Sales order'],'Recognize the main procurement, sales, and accounting document flows.','MM procurement commonly moves from requisition to purchase order, goods receipt, and invoice. SD commonly moves from sales order to delivery, goods issue, and billing. FI records accounting impact; document relationships vary by configuration.','A useful ABAP report presents the right business status and avoids confusing documents with similar names.','MM: Requisition → Purchase Order → Goods Receipt → Invoice\nSD: Sales Order → Delivery → Goods Issue → Billing\nFI: Accounting document records financial postings','These are simplified flows. Real systems add approvals, returns, pricing, and organization-specific steps.','Pick one flow and list the question a user would ask at each step, such as “Has this order shipped?”','A one-page flow with the key business question and likely document at each stage.','Which sequence best describes a simplified procurement flow?',['Sales order → billing → requisition','Purchase requisition → purchase order → goods receipt → invoice','Billing → goods issue → purchase order','Accounting document → delivery → requisition'],1,'That is the common procure-to-pay sequence in the roadmap.'),
  lesson('m1-landscape',1,2,'SAP architecture, clients, and transports','Theory','Beginner',40,['Application server','Client','Package','Transport'],'Explain how development objects move safely between SAP environments.','Developers create repository objects in packages, test changes in a development system, and move approved changes through the landscape using transports. A client is a logical partition; it is not a separate code repository.','Understanding the lifecycle prevents local fixes from bypassing review or reaching production unexpectedly.','Development → Quality → Production\nRequest: ZCL_ORDER_REPORT → package ZLEARNING → transport request','The object is assigned to a package and recorded in a transport request so the change can be reviewed and imported. Landscape names and release steps vary by organization.','Sketch a three-system landscape and write down what evidence should be checked before a transport is released.','A diagram with a transport path and a short pre-release checklist.','What is the purpose of a transport request?',['To store end-user passwords','To group and move repository/configuration changes through a landscape','To replace a database table','To compile a Fiori page'],1,'Transports carry controlled changes between SAP systems.'),
  lesson('m1-adt',1,2,'Set up ADT and create your first report','Lab','Beginner',50,['ADT','Eclipse','ABAP program'],'Navigate ABAP Development Tools and run a small executable report.','ADT is the Eclipse-based development environment for ABAP. Access requires a compatible ABAP system, account, and project connection; trial availability and setup depend on current SAP offerings.','Your editor and system connection are where code, syntax checks, activation, and debugging meet.','REPORT z_hello_khoa.\n\nWRITE: / |Hello, { sy-uname }|.','The report statement declares an executable program. `sy-uname` is a system field; the string template inserts the current user at runtime.','Connect ADT to an authorized practice system, create a report in your own namespace, activate it, and run it.','An activated report with captured output and a note of the system/release used.','Which step makes a repository change usable in the ABAP system?',['Renaming the file locally','Activating the object after a successful check','Opening the package explorer','Adding a comment'],1,'Activation generates the active runtime version after checks pass.'),
  lesson('m1-values',1,3,'ABAP variables, types, and expressions','Coding','Beginner',45,['DATA','TYPES','Constants','Data types'],'Declare typed values and use expressions without relying on implicit conversions.','ABAP declarations describe the data shape up front. Prefer meaningful names and suitable built-in or Dictionary types; currency and quantity values also need their associated semantics.','Clear types reduce conversion defects and make business values easier to understand in reviews.','TYPES ty_amount TYPE p LENGTH 8 DECIMALS 2.\nDATA lv_net_amount TYPE ty_amount VALUE \'125.50\'.\nCONSTANTS gc_tax_rate TYPE decfloat16 VALUE \'0.08\'.\nDATA(lv_gross) = lv_net_amount * ( 1 + gc_tax_rate ).','The local type gives the amount a fixed decimal scale. The constant names a rule; the inline declaration infers the result type where supported by the release.','Declare a quantity, unit, and calculated subtotal for an order item. Add a named constant for a test discount.','A small executable example with explicit types and two understandable assertions or output values.','Why should an amount carry an appropriate type and decimal definition?',['To make every variable a string','To avoid confusing precision and conversion behavior','To shorten every program','To prevent activation'],1,'Numeric business values need deliberate precision and semantics.'),
  lesson('m1-flow',1,3,'Conditions, loops, and safe control flow','Coding','Beginner',45,['IF','CASE','LOOP','CHECK'],'Choose control-flow statements that express a business rule clearly.','Conditions select a path; loops process collections. Guard clauses and explicit branches help readers see what happens when input is missing or a status is unsupported.','A report must handle boundary cases predictably, such as an empty result or blocked document.','IF lv_status = \'OPEN\'.\n  WRITE / \'Needs review\'.\nELSEIF lv_status = \'CLOSED\'.\n  WRITE / \'Complete\'.\nELSE.\n  WRITE / \'Check status mapping\'.\nENDIF.','Each branch describes one known state; the final branch makes an unmodeled state visible instead of silently treating it as complete.','Add a status decision for open, completed, and unknown values, then test one input for each branch.','Three explicit outcomes, including a safe message for an unexpected status.','What should happen when a status value is not recognized?',['Assume it is complete','Handle it explicitly or report that it needs review','Delete the record','Skip all validation'],1,'Unknown values should not be silently misclassified.'),
  lesson('m1-tables',1,4,'Internal tables and work areas','Coding','Beginner',55,['Internal table','Structure','APPEND','LOOP'],'Store and process a typed set of rows in application memory.','An internal table is a typed in-memory collection. A structure describes one row, and a work area or field symbol gives code access to a row while processing.','Many ABAP tasks transform query results before presenting them or applying business rules.','TYPES: BEGIN OF ty_order,\n         order_id TYPE string,\n         status   TYPE string,\n       END OF ty_order.\nDATA lt_orders TYPE STANDARD TABLE OF ty_order WITH EMPTY KEY.\nAPPEND VALUE #( order_id = \'450001\' status = \'OPEN\' ) TO lt_orders.','The line type defines the row shape. `VALUE #(...)` constructs a row using that inferred type.','Create a typed table of three sample purchase orders and count how many are open.','The table has three rows and the count includes only rows whose status is OPEN.','What does an internal table represent?',['A persisted database table in all cases','An in-memory collection of typed rows','A transport request','A screen element'],1,'Internal tables hold rows in an ABAP program’s memory.'),
  lesson('m1-sql',1,4,'Open SQL and the database boundary','Coding','Beginner',55,['Open SQL','SELECT','WHERE','Database'],'Read only the fields and rows needed for a business question.','Open SQL is ABAP’s database-independent SQL interface. Use host variables with `@`, explicit field lists, and restrictive predicates; syntax availability varies by ABAP release.','Database filtering and projection reduce transferred data and make report intent reviewable.','SELECT FROM zpo_header\n  FIELDS purchase_order, supplier, status\n  WHERE status = @lv_status\n  INTO TABLE @DATA(lt_orders).','The database filters rows before transfer. An explicit field list keeps the result focused. The Z-table here is an illustrative custom object and must exist in a real system.','Write a query for one supplier and one date range. Decide which columns the ALV actually needs.','A query with explicit fields and both supplier and date conditions.','Where should a selective filter normally be applied?',['After transferring every row to ABAP','In the database query when the criterion belongs to the data selection','Only in the user interface','In a comment'],1,'Database-side filtering avoids needless result transfer.'),
  lesson('m2-ddic',2,5,'DDIC: domains, data elements, and tables','Theory','Beginner',55,['DDIC','Domain','Data element','Transparent table'],'Explain how reusable Dictionary definitions give fields type and meaning.','A domain describes technical value properties and constraints; a data element adds field-level meaning and labels. Structures group fields; transparent tables persist application data.','Shared definitions improve consistency across database fields, programs, search helps, and screens.','@EndUserText.label: \'Order status\'\nstatus : abap.char(1);','In a CDS example, a typed element declares technical shape; production objects may reference Dictionary elements and use release-specific syntax. Prefer one canonical status definition.','Design the key, amount, currency, and status fields for an order-monitoring record. State where a domain or data element is reusable.','A compact field design with a key, semantically named amount and currency, and constrained status.','Which layer adds business-facing field meaning and labels?',['Domain','Data element','Database index','Work area'],1,'A data element supplies semantic field meaning and labels.'),
  lesson('m2-selects',2,5,'Open SQL joins, aggregation, and updates','Coding','Intermediate',60,['JOIN','GROUP BY','UPDATE','MODIFY'],'Shape multi-table reads and choose safe data-changing statements.','Join related data in the database when the relationship is clear. Use aggregate functions for grouped summaries. INSERT adds rows, UPDATE changes matching rows, MODIFY uses a table key for insert-or-update behavior, and DELETE removes matching rows. Data changes require authorization, validation, correct keys, and transaction handling appropriate to the application.','A report that queries related document data efficiently is more useful than one that repeatedly looks up each row.','SELECT FROM zpo_header AS h\n  INNER JOIN zpo_item AS i ON i~purchase_order = h~purchase_order\n  FIELDS h~purchase_order, h~supplier, COUNT( * ) AS item_count\n  GROUP BY h~purchase_order, h~supplier\n  INTO TABLE @DATA(lt_summary).','The join connects header to items using the key. Aggregation returns one row per grouped purchase order and supplier. Syntax details depend on release.','Extend a read-only monitoring query to show item counts. Then describe which safeguards a separate update operation would need.','A grouped result with one row per order plus a written update-safety checklist.','Why prefer a join over one SELECT per header row?',['It avoids repeated database round trips and expresses the relation together','It always creates fewer rows','It removes authorization checks','It bypasses the database'],0,'A join can fetch related data in one database request and keeps the relationship explicit.'),
  lesson('m2-debug',2,6,'Debugging: breakpoints, stepping, and state','Lab','Beginner',55,['Breakpoint','Call stack','Watchpoint','Debugger'],'Trace a reproducible defect from the user-visible symptom to the responsible state change.','A breakpoint pauses execution. Step over a call, step into relevant code, inspect the call stack and variables, and use a watchpoint when a value changes unexpectedly.','Debugging replaces guesses with evidence about control flow and data.','"Input order=450001 → breakpoint before calculation → inspect lt_items → step over total update → compare expected and actual"','Record the exact input and the first line where the state diverges. Inspect internal-table keys and field values before changing code.','Debug a total that is too high. Use two items, record intermediate values, and identify the first incorrect calculation.','A short defect note with reproduction, failing line/state, root cause, and a verified correction.','What is the most useful point to place the first breakpoint?',['Anywhere at program start permanently','Near the first operation suspected to violate the expected behavior','Only after the program ends','Inside unrelated code'],1,'Start near the suspected state transition so evidence narrows the search.'),
  lesson('m2-oo',2,6,'ABAP OO: classes, methods, and interfaces','Coding','Intermediate',55,['Class','Object','Method','Interface'],'Separate report orchestration from reusable business logic.','A class defines behavior and state; an object is an instance. Visibility separates public contracts from private details. Constructors establish valid initial state. Inheritance shares behavior, polymorphism lets callers use a common interface for different implementations, and static members belong to the class rather than one instance.','A small OO boundary makes calculations easier to test and reduces tightly coupled report code.','CLASS zcl_order_total DEFINITION PUBLIC FINAL CREATE PUBLIC.\n  PUBLIC SECTION.\n    METHODS calculate IMPORTING iv_net TYPE decfloat16\n                      RETURNING VALUE(rv_total) TYPE decfloat16.\nENDCLASS.','The method signature exposes only the input and result. An implementation can apply the approved rule without knowing about the selection screen or ALV.','Move one calculation out of an executable report into a class, then call it with valid and boundary values.','A focused class with one clear responsibility and no screen or database dependency.','What does an interface primarily define?',['A stable contract for callers','A database connection','A transport order','A loop counter'],0,'An interface exposes a contract independent from a concrete implementation.'),
  lesson('m2-exceptions',2,7,'Exceptions and defensive boundaries','Coding','Intermediate',45,['Exception','RAISING','TRY','CATCH'],'Make expected failure paths explicit and preserve useful diagnostic context.','Exceptions signal failures across a call boundary. Catch an exception where the program can recover or add user-relevant context; do not convert every failure into success-shaped output.','A failed data conversion or unavailable dependency should be diagnosable rather than silently ignored.','TRY.\n    lo_reader->load( iv_order = lv_order ).\n  CATCH cx_root INTO DATA(lx_error).\n    MESSAGE lx_error->get_text( ) TYPE \'E\'.\nENDTRY.','Catching the broad root class is shown for illustration; production code should catch the narrow expected exception and log appropriate context.','Choose one anticipated invalid input for your report and decide whether to reject it, retry, or show a message.','A failure path that explains the problem, keeps the program state safe, and can be tested.','Where should an exception usually be caught?',['At a boundary that can recover or explain it meaningfully','Inside every statement','Only in the database','Nowhere, always ignore it'],0,'Handle failures at a boundary with enough context to respond correctly.'),
  lesson('m2-alv',2,7,'ALV: present a useful operational report','Lab','Intermediate',50,['ALV','Field catalog','Layout'],'Turn selected data into a readable list users can sort and investigate.','ALV is a family of SAP list viewers. A useful report labels columns, chooses sensible widths and totals, and gives users a stable business key for navigation. The API differs across classic and newer environments.','The report succeeds only if a user can answer the original question quickly and trust each row.','"Supplier | Purchase Order | Created On | Item Count | Net Value | Status"\nTotals: Net Value\nSort: Status, Created On','Define a display model deliberately rather than exposing a raw database structure. Document which values are derived and how.','Design an ALV field list for late purchase orders. Mark key, date, amount/currency, and status fields.','A field catalog or UI specification with meaningful labels, order, currency semantics, and a useful sort.','What makes an operational ALV trustworthy?',['Displaying every technical field','Clear labels, relevant fields, and correct business meaning','Color alone','Hiding the source of totals'],1,'Users need relevant data with clear semantics and traceable values.'),
  lesson('m2-integrations',2,8,'BAPI, RFC, and enhancement basics','Theory','Intermediate',55,['BAPI','RFC','BAdI','Enhancement'],'Distinguish stable business APIs, remote calls, and extension points.','A BAPI is a standardized business API convention; RFC is a communication mechanism for calling remote-enabled function modules. BAdIs provide defined extension hooks. Availability and release status are system-specific.','Integration should use supported contracts and extension points instead of changing vendor code directly.','Caller → released business API → SAP business object\nExtension point: BAdI implementation','Check the target system’s documentation and API release state. Classic availability does not automatically mean an API is released for ABAP Cloud use.','For a purchase-order change requirement, list what you would verify before selecting a BAPI or BAdI.','An API decision note covering semantics, released status, errors, commits, and test environment.','What does RFC describe?',['A remote function call mechanism','A data element','An ALV variant','An authorization role'],0,'RFC is a mechanism for remote communication with function modules.'),
  lesson('m2-project',2,8,'Project 1: design and test the order monitor','Project','Intermediate',90,['Project 1','Open SQL','ALV','ABAP OO'],'Deliver an order-monitoring report from a written requirement through test evidence.','A credible report explains its selection criteria, joins, totals, exception paths, and limits. Split data retrieval from display and calculation so each part can be inspected.','This project proves the practical Classic ABAP abilities expected at the first portfolio milestone.','Requirement → Technical design → Query/model → ALV → Debug → Test evidence','Trace every displayed field back to a source or documented calculation. Include empty results, invalid ranges, and high-volume behavior in test cases.','Build the report using your available practice-system tables or clearly documented sample data. Write a README and an English demo script.','Activated source, technical notes, test cases/results, performance reasoning, and a 3–5 minute demo.','Which artifact shows that the delivered report meets the written requirement?',['A screenshot alone','A test case with expected and actual results tied to the requirement','A longer class name','A copied standard program'],1,'Requirement-linked test evidence demonstrates behavior against expectation.'),
  lesson('m3-modern',3,9,'Modern ABAP syntax for clearer intent','Coding','Intermediate',50,['Inline declaration','VALUE','COND','String template'],'Use modern expressions to express construction and decisions close to their purpose.','Constructor operators such as VALUE and COND can reduce temporary variables. Inline declarations infer a type from context. SWITCH selects among discrete values; string templates format readable output. FOR, FILTER, and REDUCE can build, select, and aggregate collections. Availability depends on the ABAP release and language version.','Concise syntax helps readers see the transformation, provided expressions remain understandable.','DATA(lv_label) = COND string( WHEN lv_count = 1 THEN `1 item`\n                                ELSE |{ lv_count } items| ).\nDATA(lt_ids) = VALUE string_table( ( `450001` ) ( `450002` ) ).','COND selects a value from conditions. VALUE constructs a typed table. Prefer a named intermediate value when one expression becomes hard to scan.','Refactor a nested IF that labels an order status using COND. Keep an explicit fallback for an unknown status.','Same results as before, including an unknown-status fallback, with a short readable expression.','What is a sound reason to use a constructor expression?',['To make code shorter at any cost','To express a value construction or decision clearly at the point of use','To hide business rules','To avoid types'],1,'Modern syntax is valuable when it makes intent clearer.'),
  lesson('m3-expressions',3,9,'Table expressions, FOR, FILTER, and REDUCE','Coding','Intermediate',55,['FOR','FILTER','REDUCE','Table expression'],'Transform collections without losing clarity about keys, missing rows, and totals.','Table expressions access rows by key or index. FOR builds a result, FILTER selects matching rows with suitable keys, and REDUCE combines values. Exact capabilities depend on release.','These tools can replace noisy loops while preserving typed, testable transformations.','DATA(lv_sum) = REDUCE decfloat16( INIT total = CONV decfloat16( 0 )\n  FOR row IN lt_items NEXT total = total + row-net_amount ).','The accumulator starts at zero and adds each row’s net amount. For missing table-expression entries, use safe handling such as OPTIONAL or explicit existence checks where supported.','Calculate the number and total value of open sample orders using both a readable loop and a modern expression; compare them.','Both versions return the same result and the chosen version remains easy for a teammate to review.','What should be considered before using a table expression by key?',['Whether the key exists and how a missing row is handled','The screen color','The number of comments','The package description'],0,'Missing-key behavior must be deliberate to avoid a runtime exception.'),
  lesson('m3-sql',3,10,'Modern Open SQL and query design','Coding','Intermediate',50,['Open SQL','Host variables','SQL expressions'],'Build readable data access with explicit fields, host variables, and selective predicates.','Modern Open SQL supports expressions and a consistent host-variable marker. Push filtering and aggregation down where appropriate; inspect the target release syntax and database plan for expensive queries.','A clear query defines both the result shape and the amount of data the app asks the database to return.','SELECT FROM zpo_item\n  FIELDS purchase_order, SUM( net_amount ) AS net_total\n  WHERE currency = @iv_currency\n  GROUP BY purchase_order\n  INTO TABLE @DATA(lt_totals).','The host variable is marked with `@`. The aggregation stays at the data source, and the selected result is small. Illustrative custom table fields must match a real schema before use.','Add a date condition and a maximum result rule to a monitoring query. Explain how you will confirm the chosen predicate is selective.','A query with explicit projection, selective conditions, and a validation plan for the system’s data volume.','Why use `@` for an ABAP host variable in modern Open SQL?',['It distinguishes an ABAP value from a database column','It forces an index','It defines a CDS association','It means null'],0,'The marker makes the ABAP host value explicit in the SQL statement.'),
  lesson('m3-cds',3,10,'CDS view entities and semantic data models','Theory','Intermediate',55,['CDS','View entity','Annotations','S/4HANA'],'Explain how CDS entities model reusable, semantically rich data for services and applications.','ABAP CDS defines data models in the ABAP repository. View entities express reusable projections and relationships; annotations add semantics for consumers. Syntax, available annotations, and data sources are release-dependent.','A deliberate data model can serve reporting and applications without each consumer rebuilding joins and labels.','@EndUserText.label: \'Open purchase orders\'\n@AccessControl.authorizationCheck: #CHECK\ndefine view entity ZI_OpenPurchaseOrder\n  as select from zpo_header\n{ key purchase_order as PurchaseOrder,\n      supplier      as Supplier,\n      created_on    as CreatedOn }\nwhere status = \'O\'','The entity projects a stable business-facing shape and declares an authorization policy. A real implementation needs valid sources and an appropriate access control role.','Create a CDS view entity design for open orders. Identify keys, labels, filters, and whether a DCL role is required.','A view design with stable keys, meaningful names, a justified filter, and an authorization decision.','What is a useful role of CDS annotations?',['Provide metadata and semantics to consuming tools/frameworks','Replace every authorization check','Store a user’s browser theme','Run a transport'],0,'Annotations add semantic metadata that tools and consumers can interpret.'),
  lesson('m3-cds-relations',3,11,'CDS associations, joins, and authorization','Coding','Intermediate',55,['Association','Join','DCL','Authorization'],'Model relationships and protect data access at the appropriate layer.','A join combines rows in one query; an association models a navigable relationship in the data model. CDS access control can apply role-based row restrictions when configured and supported. Parameters can scope a view at read time; calculated elements can derive values. Analytical annotations and aggregation are useful when the consumer needs analytical semantics, subject to the target release and scenario.','Good relationships avoid duplicated logic, while authorization protects data wherever a consumer reads it.','association [0..1] to I_Supplier as _Supplier\n  on $projection.Supplier = _Supplier.Supplier\n\n@AccessControl.authorizationCheck: #CHECK','The cardinality communicates the expected relationship. The authorization annotation alone does not define the policy: access-control roles and the consuming path must also be correct.','Model a supplier association and write down who may read each company code. Test both an allowed and a denied identity.','A relationship model plus a role/access test matrix that distinguishes visibility from UI hiding.','Does hiding a field in a UI alone secure the underlying data?',['Yes, for every consumer','No; enforce access rules at an appropriate backend layer','Only when using CDS','Only for administrators'],1,'UI hiding is not a substitute for backend authorization.'),
  lesson('m3-doc',3,12,'Write an English technical specification','English','Intermediate',45,['Technical Specification','CDS','Project documentation'],'Translate a functional request into a concise, testable technical design.','A useful specification records scope, source data, mapping, validations, authorization, failure behavior, and tests. State assumptions separately from confirmed requirements.','Clear English design notes help reviewers understand the implementation before opening the code.','Requirement: List open orders older than 30 days.\nDesign: CDS entity projects order, supplier, created date, status. Service query applies company-code authorization.\nAssumption: “Older” uses document creation date.','Each sentence adds a decision a developer or tester can validate. The assumption invites clarification before a disputed rule is coded.','Write a one-page design for the Project 2 root entity and its supplier relationship. Include one open clarification.','A concise English specification with data shape, security, behavior, and at least three acceptance checks.','Why record an assumption in the specification?',['To present an unverified choice as a fact','To expose a decision that needs confirmation before implementation','To avoid tests','To replace the requirement'],1,'Visible assumptions let the team resolve uncertainty early.'),
  lesson('m4-rap',4,13,'RAP architecture from CDS to application','Theory','Intermediate',55,['RAP','Business object','Behavior','Service binding'],'Trace how a RAP model becomes a consumable OData service and Fiori app.','RAP combines CDS-based modeling, behavior, service definition, and service binding. It standardizes transactional ABAP services; exact supported features depend on the ABAP platform and release.','Knowing the layers makes errors easier to locate and helps you explain the architecture in a review.','CDS model → Behavior → RAP business object → Service definition → Service binding / OData → Fiori Elements','Each artifact has a focused responsibility: shape, transactional rules, exposure, protocol, and UI consumption. Not every project needs every layer or a generated UI.','Draw the artifacts for a root order entity with items and label where CRUD, validation, and OData exposure are configured.','A layer diagram with one sentence about the role and likely defect location for each artifact.','Which artifact defines the protocol binding for a business service?',['Behavior implementation','Service binding','Database index','ABAP package'],1,'The binding selects the service type/protocol for an exposed service.'),
  lesson('m4-managed',4,13,'Managed and unmanaged RAP scenarios','Theory','Intermediate',50,['Managed RAP','Unmanaged RAP','Transactional buffer'],'Choose a RAP implementation model based on ownership of persistence and transactional logic.','Managed RAP delegates standard transactional processing to the framework while you implement business behavior. Unmanaged RAP gives the application more responsibility for operations and persistence integration.','Selecting the simplest fitting model avoids unnecessary low-level work and makes ownership explicit.','Managed: framework handles standard create/update/delete; developer adds validations/actions.\nUnmanaged: application provides required operation/query implementation.','The managed scenario fits many new business objects. Legacy integration or special persistence behavior may require unmanaged implementation; confirm capability on the target release.','For a new custom request entity and an existing legacy order API, choose a model for each and justify the boundary.','A short decision with framework/application responsibility and known constraints clearly stated.','In a managed RAP BO, who typically handles standard transactional processing?',['The RAP managed runtime','The browser only','An ALV layout','The transport system'],0,'Managed runtime provides generic transactional handling for standard operations.'),
  lesson('m4-behavior',4,14,'RAP behavior: validations, determinations, and actions','Coding','Intermediate',60,['Validation','Determination','Action','Locking'],'Assign business rules to the behavior hook that matches their purpose.','A validation rejects invalid state, a determination derives or adjusts values, and an action represents an explicit business operation. The BO also needs deliberate locking and numbering strategies; draft handling supports editable in-progress state where the app scenario and platform require it. These capabilities and syntax depend on the BO and release.','Rules placed in the right hook remain consistent across service consumers.','Validation: reject requested date before order date.\nDetermination: derive gross amount from items.\nAction: release an order after approval.','A validation reports a business error without hiding it. A determination computes state; an action is a named operation, not an arbitrary UI button handler.','Map three purchase-order rules to validation, determination, or action. Add the expected message and a positive/negative test for each.','A behavior matrix linking trigger, rule, output/message, and test case.','Which RAP behavior fits deriving a total whenever item values change?',['Validation','Determination','Service binding','Authorization role'],1,'A determination derives or adjusts values based on a trigger.'),
  lesson('m4-service',4,14,'Service definition, binding, and OData','Lab','Intermediate',55,['Service definition','Service binding','OData'],'Expose only the business model and operations required by a consumer.','A service definition selects model elements for exposure. A service binding connects that service to a protocol and service type, such as an OData variant supported by the system.','Explicit service boundaries help keep APIs stable and avoid exposing internal implementation details.','define service ZUI_ORDER_MONITOR {\n  expose ZC_Order as Orders;\n}\n\n// Activate, bind to a supported OData service type, publish, then inspect metadata.','The projection view is exposed under a consumer-facing name. In ADT, activation and publication steps vary by service binding type and platform release.','Expose only the root entity and one value help needed by your app. Inspect metadata and try a read request in the service preview.','A published service with verified metadata, a successful read, and a short list of intentionally hidden fields.','What is the purpose of a service definition?',['Select which modeled entities are exposed as a business service','Implement each database update','Define browser navigation','Create an SAP client'],0,'It defines the exposed model/behavior surface for the service.'),
  lesson('m4-fiori',4,15,'Fiori Elements and metadata-driven UI','Theory','Intermediate',45,['Fiori Elements','List Report','Object Page','UI annotation'],'Explain how annotations help create a standard Fiori UI from an OData service.','Fiori Elements provides metadata-driven page patterns, including List Report and Object Page. CDS UI annotations describe presentation semantics; the service and metadata must support the chosen fields and operations.','An ABAP developer can contribute a usable app without building every frontend component from scratch.','OData metadata + UI annotations → List Report → Object Page','Annotations influence labels, columns, filters, and navigation. Always validate the generated UI against real tasks and role requirements.','Sketch a list and object page for purchase orders. Choose default columns, a filter, and one meaningful navigation target.','A page outline tied to exposed service fields and a user task, plus a note of one UI behavior to validate.','What primarily drives a Fiori Elements page structure?',['Service metadata and UI annotations','An ALV field catalog only','A transport request','A browser bookmark'],0,'Metadata and annotations guide the generated page patterns.'),
  lesson('m4-test-auth',4,16,'Authorization and testing for a RAP service','Lab','Intermediate',55,['Authorization','ABAP Unit','Integration test'],'Test both business behavior and the access boundary exposed through the service.','Authorization determines who may access which instance or operation. Unit tests target isolated logic; integration/service checks cover model, behavior, and exposure. Use least privilege and test negative cases.','A CRUD demo is incomplete if unauthorized users can read or change the same data.','Role A: display company 1000 → GET allowed\nRole B: company 2000 only → GET company 1000 denied\nValidation: negative amount → save rejected','The matrix makes access expectations testable. UI visibility and backend authorization are separate concerns. Use only safe, non-production test data.','Write a test matrix with allowed/denied reads, create, update, invalid data, and service metadata checks.','Named test identities, expected responses, actual evidence, and a defect note for any mismatch.','What must a useful authorization test include?',['An allowed path only','Both expected allowed and denied paths at the backend boundary','A UI screenshot only','A developer’s assumption'],1,'Negative cases prove restricted access is actually enforced.'),
  lesson('m5-cloud',5,17,'ABAP Cloud and released APIs','Theory','Intermediate',50,['ABAP Cloud','Released API','Language version'],'Explain how a cloud-ready language version constrains dependencies and extensions.','ABAP Cloud is a development model and language version with governed APIs and extensibility. Only APIs released for the applicable contract are valid dependencies in that context; exact allowed APIs vary by system and release.','Released contracts support upgrade-safe development and clarify which dependencies SAP supports.','Custom app → released API contract → SAP business object','Check API state in the target environment and choose an extension point meant for custom development. A familiar classic API may be unavailable in a cloud language version.','For a requirement to read supplier data, compare a released API choice with a direct table read and explain the upgrade impact.','A dependency note naming the API contract to verify, data needed, and fallback clarification if unavailable.','What should you confirm before using an SAP API in ABAP Cloud?',['That the name appears in a search result','That it is released for the intended language version and contract','That it works in one old system','That it has a short signature'],1,'API release state governs supported use in the target development context.'),
  lesson('m5-clean-core',5,17,'Clean Core and extension choices','Theory','Intermediate',45,['Clean Core','Extension','Modification'],'Choose an extension approach that preserves upgradeability and isolates custom behavior.','Clean Core is a strategy for minimizing disruption to the standard core through supported configuration and extension patterns. The right choice depends on edition, release, and extensibility tier.','Modifying standard code creates upgrade and support risk; a defined extension point keeps custom behavior easier to review and maintain.','Requirement → configuration? → key-user extension? → developer extensibility? → side-by-side integration?','Evaluate the requirement and system’s allowed extensibility options before coding. Record why a choice fits rather than treating “cloud” as a blanket answer.','Classify a field validation, a custom approval workflow, and an external reporting integration by likely extension approach.','A decision table that states fit, constraint, API/extension point to verify, and lifecycle concern.','Why can changing standard SAP code create lifecycle risk?',['It can conflict with upgrades and future support changes','It uses too few variables','It cannot be documented','It makes a query return rows'],0,'Direct changes to standard code can be overwritten or complicate upgrades/support.'),
  lesson('m5-perf',5,18,'Performance: database, tables, and measurement','Coding','Intermediate',50,['Performance','JOIN','Hashed table','Trace'],'Find the actual expensive step and select an appropriate optimization.','Avoid database access inside loops when a set-based query is possible. Use a table type whose key matches lookup needs, minimize transferred columns, and measure on representative data.','Performance depends on data volume and access pattern; intuition alone often optimizes the wrong operation.','"Before: loop headers → SELECT items per header"\n"After: select related rows in one query, then index by order key"','A hashed table can give efficient key lookups when uniqueness fits. Sorted tables support ordered/key access. Confirm behavior and memory cost with a trace or measurement.','Inspect one slow scenario and write down query count, rows transferred, and time before proposing a change.','A reproducible baseline, one targeted change, and comparable measurements with identical input.','What should happen before a performance rewrite?',['Measure a representative workload and identify the expensive operation','Change every internal table to hashed','Remove all filters','Optimize variable names'],0,'A measurement identifies which change can improve the actual bottleneck.'),
  lesson('m5-unit',5,18,'ABAP Unit, regression, and evidence','Lab','Intermediate',50,['ABAP Unit','Test double','Regression'],'Create tests that protect business rules and document observed outcomes.','ABAP Unit tests executable behavior in isolation where possible. Integration tests check dependencies and service behavior. Regression cases preserve previously correct outcomes after a change.','Tests let you change a portfolio project confidently and explain quality evidence in an interview.','METHOD calculates_discount FOR TESTING.\n  cl_abap_unit_assert=>assert_equals(\n    act = cut->calculate( iv_net = \'100\' )\n    exp = \'90\' ).\nENDMETHOD.','The test calls the unit under test and compares actual with expected. A realistic suite also tests boundary values and invalid inputs.','Add one happy-path, one boundary, and one invalid-input test for a Project 2 determination.','Tests name the scenario, expected rule, and observed result; failure messages help locate the problem.','What is a regression test for?',['Proving an existing behavior still works after a change','Measuring interview confidence','Publishing an OData binding','Replacing code review'],0,'Regression tests protect behavior that was already correct.'),
  lesson('m5-project2',5,19,'Project 2: complete and review the application','Project','Advanced',90,['Project 2','RAP','OData','Portfolio'],'Finish the Modern S/4HANA application and package convincing technical evidence.','The project connects CDS, RAP behavior, a service definition/binding, OData, and a Fiori Elements consumer. It includes CRUD, validation, authorization, tests, and Clean Core decisions.','This is the principal demonstration of modern ABAP readiness and end-to-end thinking.','Data model → Behavior → Service → UI\nEvidence: architecture, API/release choices, test results, demo','Review each boundary against the requirement. Do not claim a feature is portable until tested on the stated system release.','Complete the build in an available ABAP system or document the exact unverified system-dependent steps; create English README and demo flow.','Source or reproducible build notes, architecture diagram, test evidence, known constraints, and a 10-minute demo.','What makes a portfolio claim credible?',['A technology list without evidence','A clear requirement, implementation explanation, and reproducible test/demo evidence','A screenshot with no context','An unsupported “production-ready” label'],1,'Evidence lets a reviewer verify what was built and on which assumptions.'),
  lesson('m6-cert',6,20,'Certification domains and a focused review plan','Review','Intermediate',45,['Certification','Knowledge gaps','SAP Learning'],'Create a certification plan based on current official exam information and measured gaps.','The roadmap targets Backend Developer – ABAP Cloud or a current equivalent. Certification names, format, and availability change; verify the live SAP certification page before booking. Study official learning journeys and use mock questions to identify weak domains.','A planned review turns broad study into targeted recall without distracting from hands-on practice.','Gap log: RAP behavior 2/5 → review official unit → rebuild validation → explain without notes','Keep certification as one signal alongside working code, English communication, and project evidence. Do not assume an old exam blueprint remains current.','Create a 10-domain confidence score and schedule three focused review sessions for your weakest areas.','A dated study plan linking gaps to official SAP learning material and a decision to verify exam details before booking.','Where should you verify current certification and exam details?',['An old saved screenshot','SAP’s official learning/certification platform','A forum answer alone','A course sales page'],1,'Use the current official SAP platform for time-sensitive certification details.'),
  lesson('m6-interview',6,20,'Technical interview: explain trade-offs clearly','Interview','Intermediate',45,['Interview','ABAP OO','Open SQL','CDS'],'Answer technical questions with a concise definition, example, and trade-off.','A strong answer starts with the direct idea, gives a small example, then names a limitation or decision criterion. If uncertain, state what you would verify in the system or official docs.','Interviewers assess reasoning and communication as well as terminology.','Question: “Why avoid SELECT in a loop?”\nAnswer: “It can create repeated database round trips. I would usually fetch related data set-wise, then measure with representative input. A loop may still be acceptable for tiny data or a specific API boundary.”','The answer connects a principle to an action and a condition. Avoid claiming that one pattern is always best.','Record a two-minute answer about CDS vs a classic report and review it for clarity, evidence, and version caveats.','A concise recording or written transcript with one concrete example and a justified trade-off.','What improves a technical interview answer most?',['More acronyms per sentence','A direct explanation, a relevant example, and a reasoned limitation','Avoiding all uncertainty','Reciting code without context'],1,'A clear example plus a trade-off demonstrates applied understanding.'),
  lesson('m6-english',6,21,'Global delivery: meetings, clarification, and incidents','English','Intermediate',45,['Daily meeting','Requirement clarification','Incident update'],'Give a concise project update and ask precise questions in working English.','Use a simple structure: context, current status, next action, blocker. For incidents, separate symptom, evidence, cause, impact, and resolution; distinguish confirmed facts from hypotheses.','Clear updates let teammates coordinate across time zones and prevent untested assumptions.','“Yesterday I added the order filter. Today I’ll test the authorization cases. I’m blocked because the released supplier API is unavailable in our tenant. Could you confirm the approved alternative?”','The update contains work, plan, blocker, and a direct question. It names what is unavailable rather than blaming a teammate or overstating a root cause.','Prepare a 60-second daily update and a requirement clarification for a mandatory-field ambiguity.','Two short spoken scripts with specific facts, polite questions, and one next step each.','What is a useful phrase when an issue is not yet understood?',['“The root cause is definitely…”','“I have reproduced the symptom; I’m checking the data and call path to confirm the cause.”','“It is someone else’s fault.”','“It is fixed” before testing'],1,'Report what is confirmed and state the investigation that remains.'),
  lesson('m6-docs',6,21,'Technical documentation and test results','English','Intermediate',45,['Test Case','Technical Notes','Documentation'],'Write test cases and implementation notes that another developer can reproduce.','A test case states preconditions, steps, input, expected result, actual result, and status. Technical notes explain design choices, dependencies, authorization, and known release constraints.','Good documentation transfers knowledge and makes reviews, handover, and support more effective.','Precondition: user has company 1000 role.\nSteps: filter open orders; open order 450001.\nExpected: only authorized rows appear.\nActual: ...\nStatus: Pass/Fail','Keep expected and actual values distinct. Record the system/release and data setup when they affect reproducibility.','Document a denied-access test and one RAP validation test in English. Add actual results after running them.','A reproducible test record that separates expected behavior from observed evidence.','Why record actual results separately from expected results?',['To show what was observed and compare it honestly with the requirement','To avoid writing steps','To change the requirement after the test','To make the document longer'],0,'Separating expected and actual results exposes mismatches instead of hiding them.'),
  lesson('m6-demo',6,22,'Project demo and portfolio walkthrough','Project','Intermediate',60,['Portfolio','Presentation','Demo'],'Present both projects as a short story from user need to verified result.','A useful demo opens with the business question, shows the architecture at the level needed, performs a realistic scenario, and closes with test evidence and limitations.','A reviewer needs to understand your own decisions and contribution quickly.','Need → Design choice → Working flow → Test evidence → Trade-off / next step','Keep the walkthrough grounded in verified behavior. Clearly label sample data and anything that could not be run on a live system.','Prepare a ten-minute bilingual-to-English rehearsal covering the Classic report and Modern RAP app, then ask a peer to challenge one design choice.','A timed outline, two reproducible scenarios, and answers to “what was difficult?” and “what would you improve?”','What should a project demo establish?',['Only that the screen looks polished','The business need, your implementation choices, and evidence the behavior works','That every system version behaves identically','That you memorized every line'],1,'The demo should connect a requirement to verifiable behavior and explain decisions.'),
  lesson('m6-readiness',6,23,'Readiness review and next learning loop','Review','Intermediate',45,['KPI','Readiness','Study plan'],'Assess evidence against the PDF’s readiness criteria and choose the next concrete action.','The roadmap’s readiness signal is about 80% of the KPI targets, the ability to present both projects, and completing a technical interview in English. Treat it as a self-review, not a hiring guarantee.','An honest gap review turns six months of learning into a focused next step.','Evidence: Project 1 demo ✓ | Project 2 CRUD/auth tests ✓ | English mock 3/5 | RAP actions 2/5 → next review: behavior actions','Score evidence you can show. A topic marked “understand” should have an example or explanation to support the claim.','Review each KPI, attach one artifact or demonstration, and create a two-week follow-up plan for any high-impact gap.','A dated readiness sheet with evidence, gaps, and next actions.','Which is the strongest readiness signal?',['A high self-rating without examples','The ability to demonstrate both projects and explain test evidence in English','A list of watched videos','An exam booked before reviewing gaps'],1,'Demonstrable project and communication evidence supports readiness.'),
  lesson('m6-mock',6,24,'Mock interview: SAP backend developer','Interview','Advanced',60,['Mock interview','Problem solving','English'],'Combine SAP vocabulary, code reasoning, and clear communication in a realistic interview session.','Practice explaining a data model, a debugging approach, one performance decision, an authorization test, and an English incident update. When a release-specific detail arises, describe how you would verify it.','A timed rehearsal reveals gaps in both knowledge and explanation before a real interview.','Structure: clarify question → state principle → use project example → mention trade-off → check understanding','Use specific project evidence. Do not claim production experience for a learning project; say what you built and how you tested it.','Run a 30-minute mock with five technical questions and one behavioral question. Score accuracy, clarity, and evidence from 1–5.','A scorecard with one recorded answer to improve and a scheduled practice action.','What should you do when you are unsure about a release-specific answer?',['Guess confidently','State the uncertainty and explain how you would verify it for the target system','Change the subject','Claim every release is identical'],1,'Clear uncertainty paired with a verification approach is more reliable than guessing.'),
]

export function validateCurriculum(): string[] {
  const issues: string[] = []
  const ids = new Set<string>()
  for (const item of lessons) {
    if (ids.has(item.id)) issues.push(`Duplicate lesson id: ${item.id}`)
    ids.add(item.id)
    item.quiz.forEach((question, index) => {
      if (!question.options.length || question.answer < 0 || question.answer >= question.options.length) issues.push(`Invalid quiz answer: ${item.id}#${index}`)
    })
    if (!months.some((entry) => entry.month === item.month)) issues.push(`Unknown month for ${item.id}`)
  }
  return issues
}
